```
<template>
  <div>
    <header>
      <!-- navigation bar / logo -->
    </header>
    <main>
      <!-- live score dashboard -->
      <scoredashboard v-bind:scores="scores" v-on:filter="filterscores" />
    </div>
    <footer>
      <!-- links to news and social media pages -->
    </footer>
  </div>
</template>

<script>
import scoredashboard from './components/scoredashboard.vue'

export default {
  name: 'app',
  components: {
    scoredashboard
  },
  data() {
    return {
      scores: [],
      filtered_scores: []
    }
  },
  created() {
    // fetch scores from api
    this.getscores()
      .then(scores => {
        this.scores = scores
      })
  },
  methods: {
    async getscores() {
      // fetch scores from api
    },
    filterscores(filter) {
      // apply filter to scores
      // update filtered_scores
    }
  }
}
</script>
```

