```
<template>
  <div>
    <h1>{{ sport }} Scores</h1>
    <ul>
      <li v-for="game in games" :key="game.id">
        {{ game.home_team.name }} vs. {{ game.away_team.name }} - {{ game.status.type.short }}: {{ game.status.display_status }}
      </li>
    </ul>
  </div>
</template>

<script>
export default {
  name: 'Scores',
  data() {
    return {
      games: [],
      sport: ''
    }
  },
  created() {
    this.getScores();
  },
  methods: {
